    def _chain_config(q):
        """Antiprism-chain-poles family: four horizontal triangles at
        heights 0, z1, z2, z3 (z1 < z2 < z3) with independent inter-layer
        twists t1, t2, t3 (fourth derived as t1+t3), plus two axial poles
        at zp1, zp2. 9 effective DOFs; cross-layer contacts can dominate
        the min-distance, unlike ring families."""
        r, t1, t2, t3, z1, z2, z3, zp1, zp2 = [float(v) for v in q]
        ang = 2.0 * np.pi * np.arange(3) / 3.0
        layers = [np.stack([r * np.cos(ang + t), r * np.sin(ang + t),
                            np.full(3, z)], axis=1)
                  for t, z in ((t1, 0.0), (t2, z1), (t3, z2),
                               (t1 + t3, z3))]
        poles = np.array([[0.0, 0.0, zp1], [0.0, 0.0, zp2]])
        return np.vstack(layers + [poles])

    def _chain_neg(q):
        return -_ratio(_chain_config(q))
